let latest=SEED,inflight=null;
async function responseFeed(request,ctx){const cache=globalThis.caches?.default;const cacheKey=new Request(new URL('/_algo-buster-pool-v1',request.url));let data=latest;
 if(cache){try{const hit=await cache.match(cacheKey);if(hit)data=await hit.json();}catch{}}
 const stale=Date.now()-Date.parse(data.updatedAt)>5*60*1000;
 if(stale){if(!inflight){inflight=fetchPool(CHANNELS).then(async fresh=>{latest=fresh;if(cache)await cache.put(cacheKey,new Response(JSON.stringify(fresh),{headers:{'Content-Type':'application/json','Cache-Control':'public,max-age=86400'}}));return fresh;}).catch(()=>data).finally(()=>{inflight=null;});}data=await inflight;}

 return new Response(JSON.stringify(data),{headers:{'Content-Type':'application/json; charset=utf-8','Cache-Control':'no-store','X-Content-Type-Options':'nosniff'}});
}
export default {async fetch(request,env,ctx){const path=new URL(request.url).pathname;if(path==='/feed.json')return responseFeed(request,ctx);const file=FILES[path==='/'?'/index.html':path];if(!file)return new Response('Not found',{status:404});return new Response(Uint8Array.from(atob(file.data),c=>c.charCodeAt(0)),{headers:{'Content-Type':file.type,'Cache-Control':path==='/sw.js'?'no-cache':'public,max-age=0,must-revalidate','X-Content-Type-Options':'nosniff','Referrer-Policy':'strict-origin-when-cross-origin'}});}};
